"""Reference layouts and explicit ownership for the expanded shelf."""
from pathlib import Path


def integrate(root):
    root=Path(root)
    p=root/'rosa/services/IslandConfig.qml';s=p.read_text()
    if p.is_symlink():p.unlink()
    s=s.replace('"performance", "files"','"performance", "files", "clipboard", "audio", "awake", "storage", "camera", "notifications"').replace('"performance","files"','"performance","files","clipboard","audio","awake","storage","camera","notifications"')
    if 'trayShakeEnabled:' not in s:s=s.replace('readonly property var spec: ({','readonly property var spec: ({trayShakeEnabled:{type:"bool",def:true},',1)
    p.write_text(s)
    p=root/'rosa/overlays/IslandWindow.qml';s=p.read_text()
    s=s.replace('    readonly property bool wanted:\n','    readonly property bool wanted: win.dashboardRequested || win.dashboardCover || IslandConfig.s("reserveClockSpace") ||\n',1)
    s=s.replace('(win.hub.kind === "clock" || win.hub.kind === "")','!win.dashboardRequested && !win.dashboardCover && (win.hub.kind === "clock" || win.hub.kind === "")',1)
    s=s.replace('onCollapseFinished:if(!win.dashboardRequested)win.dashboardCover=false','onCollapseFinished:Qt.callLater(function(){if(!win.dashboardRequested)win.dashboardCover=false})',1)
    s=s.replace('onPressedChanged: win.pressed = pressed','acceptedButtons:Qt.LeftButton\n                onPressedChanged: win.pressed = pressed',1)
    start=s.index('            readonly property point visualRight:')
    end=s.index('            readonly property bool cam:',start)
    s=s[:start]+'            readonly property point visualRight: {\n                const edge=dot.visible && dot.opacity>0.01\n                    ? Math.max(surface.x+surface.width,dot.x+dot.width/2+dot.width/2*dot.scale*Math.max(1,dot.blobScaleX))\n                    : surface.x+surface.width;\n                const cx=stage.width/2,cy=stage.height/2;\n                const origin=stage.head+surface.width/2;\n                const progress=idleVisibility.progress*win.presentationProgress;\n                let px=origin+(edge-origin)*progress;\n                let py=cy+(stage.pillH/2-cy)*(0.85+0.15*progress);\n                px=cx+(px-cx)*(1+stage.jelly+Motion.isleSquashX*squash.value+0.016*magP.value);\n                py=cy+(py-cy)*(1-stage.jelly*Motion.isleJellyCross-Motion.isleSquashY*squash.value+0.03*magP.value);\n                px+=win.shakeX+drift.value*9+magX.value;\n                py+=magY.value;\n                return Qt.point(stage.x+cx+(px-cx)*stage.scale,stage.y+cy+(py-cy)*stage.scale);\n            }\n\n'+s[end:]
    s=s.replace('if(dashboardRequested){dashboardCover=true;collapseActivity();}', 'if(dashboardRequested){collapseActivity();}')
    s=s.replace('visible:win.visible && (win.dashboardCover)','visible:win.visible && (win.dashboardRequested || win.dashboardCover)')
    s=s.replace('            hub:win.hub', '            onSurfacePresented:if(win.dashboardRequested)win.dashboardCover=true\n            hub:win.hub',1)
    p.write_text(s)
    p=root/'rosa/overlays/IslandDashboard.qml';s=p.read_text()
    s=s.replace('    property bool entered: false','    signal surfacePresented()\n    property int surfaceFrames:0\n    onVisibleChanged:if(!visible)surfaceFrames=0\n    FrameAnimation{running:panel.visible && panel.expanded && panel.surfaceFrames<2;onTriggered:{panel.surfaceFrames++;if(panel.surfaceFrames===2)panel.surfacePresented()}}\n    property bool entered: false',1)
    s=s.replace('TapHandler{acceptedButtons:Qt.RightButton;onTapped:panel.dismissed()}','MouseArea{anchors.fill:parent;acceptedButtons:Qt.RightButton;onClicked:panel.dismissed()}')
    s=s.replace('panel.page===8 ?','panel.page===0 && ShelfState.editing ? IslandConfig.s("shelfHeight")+100:panel.page===8 ?',1)
    s=s.replace('return index===8 ?','return index===0 && ShelfState.editing ? IslandConfig.s("shelfHeight")+100:index===8 ?',1)
    # The visible catalogue is also available inline, preserving Home while editing.
    s=s.replace('Component{id:media;ShelfMedia{}}','Component{id:media;ShelfMedia{onOpenLyrics:panel.selectPage(9);onOpenSources:panel.selectPage(10)}}')
    s=s.replace('Component {id:overview;ShelfHome{onOpenPage:page=>panel.selectPage(page)}}','Component {id:overview;HomeEditor{onOpenPage:page=>panel.selectPage(page)}}')
    s=s.replace('Component{id:widgetDetail;ShelfHome{slots:[panel.detailWidget];onOpenPage:page=>panel.selectPage(page)}}','Component{id:widgetDetail;ShelfHome{slots:[panel.detailWidget];onOpenPage:page=>panel.selectPage(page)}}')
    s=s.replace('ShelfButton{implicitWidth:44;implicitHeight:36;icon:"notch/grid.svg";', 'ShelfButton{implicitWidth:44;implicitHeight:36;icon:"notch/grid.svg";')
    s=s.replace('visible:ShelfState.editing && panel.page!==8;', 'visible:ShelfState.editing && panel.page!==8 && panel.page!==0;')
    s=s.replace('index>13','index>14').replace('model:14','model:15')
    s=s.replace('    property var visitedPages:({0:true})',
        '    property var visitedPages:({0:true})\n    property int prewarmCursor:0\n    readonly property var prewarmPages:[2,5,11,13]\n    Timer{interval:250;running:panel.prewarmCursor<panel.prewarmPages.length;repeat:true;onTriggered:{const next=Object.assign({},panel.visitedPages);next[panel.prewarmPages[panel.prewarmCursor++]]=true;panel.visitedPages=next}}')
    s=s.replace('active:!!panel.visitedPages[index]','asynchronous:index!==0\n                            active:!!panel.visitedPages[index]')
    s=s.replace('awake,widgetDetail][index]','awake,widgetDetail,storage][index]')
    s=s.replace('function onReveal(page){panel.selectPage(page)}','function onReveal(page){panel.selectPage(page)}function onDetailRequested(key){panel.detailWidget=key;panel.selectPage(13)}',1)
    s=s.replace('selected:panel.page===0;onClicked:panel.selectPage(0)', 'selected:panel.page===0 || panel.page===3 || panel.page===9;onClicked:panel.selectPage(0)')
    s=s.replace('implicitHeight:44','implicitHeight:36')
    s=s.replace('radius:22;color:"#eb151517";border.width:1;border.color:"#26ffffff"','radius:18;color:"#b51b1b20";border.width:1;border.color:"#20ffffff"')
    s=s.replace('spacing:3\n            ShelfButton','spacing:6\n            ShelfButton')
    s=s.replace('implicitWidth:44;implicitHeight:36','implicitWidth:34;implicitHeight:28;flat:true;iconSize:15')
    s=s.replace('implicitWidth:34;implicitHeight:28;flat:true;iconSize:15;icon:"notch/inbox.svg"', 'implicitWidth:badge>0 ? Math.max(34,15+String(badge).length*6+10):34;implicitHeight:28;flat:true;iconSize:15;icon:"notch/inbox.svg"')
    s=s.replace('flat:true;iconSize:15;', 'flat:true;iconSize:15;foreground:selected ? ShelfStyle.primary:ShelfStyle.secondary;')
    s=s.replace('    Component {id:tray;','    Component{id:storage;StorageShelf{}}\n    Component {id:tray;',1)
    s=s.replace('panel.detailWidget==="calendar" ? 620:380','["iconSettings","navigation","batteries","translate","calendar","developer","teleprompter","vault","breather","terminal","transcribe","ring","selection","queue","jobs"].includes(panel.detailWidget) ? 620:380')
    s=s.replace('detailWidget==="calendar" ? 620:380','["iconSettings","navigation","batteries","translate","calendar","developer","teleprompter","vault","breather","terminal","transcribe","ring","selection","queue","jobs"].includes(detailWidget) ? 620:380')
    s=s.replace('13:(["calendar",','14:540,13:(["calendar",')
    s=s.replace('13:(detailWidget===','14:540,13:(detailWidget===')
    s=s.replace('({1:336,4:300','({14:300,1:336,4:300')
    s=s.replace('6:820','6:720').replace('6:280','6:250').replace('4:300','4:460')
    s=s.replace('Rectangle{anchors.fill:parent;radius:52;visible:IslandConfig.s("shelfMaterial")','Rectangle{anchors.fill:parent;radius:panel.attachedNotch ? 0:52;visible:IslandConfig.s("shelfMaterial")',1)
    s=s.replace('    readonly property int bodyHeight:', '    readonly property int audioBodyHeight:Math.min(340,78+Math.max(1,Pipewire.nodes.values.filter(n=>n.isStream && n.audio).length)*46)\n    readonly property int bodyHeight:',1)
    s=s.replace('10:300','10:panel.audioBodyHeight')
    s=s.replace('    readonly property int bodyHeight:', '    readonly property int detailBodyHeight:Math.min(output.height-80,({iconSettings:520,navigation:520,batteries:260,translate:260,ring:430,jobs:320,queue:360,developer:320,vault:360,terminal:320,teleprompter:330,transcribe:300,breather:240})[detailWidget] || IslandConfig.s("shelfHeight"))\n    readonly property int bodyHeight:',1)
    s=s.replace('({14:460,1:336','({13:panel.detailBodyHeight,14:460,1:336')
    s=s.replace('import QtQuick\n','import QtQuick\nimport QtQuick.Shapes\nimport Quickshell.Services.Pipewire\n',1)
    s=s.replace('margins.top: Math.max(0, capsuleTop)','margins.top: panel.attachedNotch ? 0:Math.max(0,capsuleTop)',1)
    s=s.replace('border.width: 1\n        border.color: "#12ffffff"','border.width:panel.attachedNotch ? 0:1\n        border.color: "#12ffffff"',1)
    s=s.replace('radius: Math.min(52, height / 2)','radius: Math.min(52,height/2)\n        topLeftRadius:panel.attachedNotch ? 0:radius\n        topRightRadius:panel.attachedNotch ? 0:radius',1)
    s=s.replace('Rectangle{visible:panel.attachedNotch;anchors.top:parent.top;width:parent.width;height:30;color:body.color}','',1)
    s=s.replace('Region { item: navigation; radius: 22 }','Region { item: navigation; radius: 18 } Region{item:notchWings}',1)
    s=s.replace('mask: Region { item: body; radius: panel.attachedNotch ? 0:52;', 'mask: Region { item:ShelfState.menuCount>0 ? panel.contentItem:body; radius:ShelfState.menuCount>0 ? 0:panel.attachedNotch ? 0:52;',1)
    s=s.replace('    ClippingRectangle {\n        id: body','    Shape{id:notchWings;visible:panel.attachedNotch && panel.geometryExpanded;anchors.top:body.top;anchors.horizontalCenter:body.horizontalCenter;width:visible ? body.width+56:0;height:visible ? 28:0;preferredRendererType:Shape.CurveRenderer\n        ShapePath{strokeWidth:-1;fillColor:"black";startX:0;startY:0\n            PathQuad{x:29;y:28;controlX:28;controlY:0}\n            PathLine{x:29;y:0}\n            PathLine{x:0;y:0}\n            PathMove{x:notchWings.width-29;y:0}\n            PathLine{x:notchWings.width-29;y:28}\n            PathQuad{x:notchWings.width;y:0;controlX:notchWings.width-28;controlY:0}\n            PathLine{x:notchWings.width-28;y:0}\n        }\n    }\n    ClippingRectangle {\n        id: body',1)
    p.write_text(s)
    qmldir=root/'island-shelf/qmldir'
    qmldir.write_text(qmldir.read_text()+'\nHomeEditor HomeEditor.qml\nTransformWindow TransformWindow.qml\nStorageShelf StorageShelf.qml\nShelfMenu ShelfMenu.qml\nShelfMenuItem ShelfMenuItem.qml\nShelfMenuSeparator ShelfMenuSeparator.qml\nDragBasket DragBasket.qml\nHomeUtility HomeUtility.qml\nDeveloperTools DeveloperTools.qml\nTeleprompter Teleprompter.qml\nVaultShelf VaultShelf.qml\nBreatherShelf BreatherShelf.qml\nTerminalShelf TerminalShelf.qml\nTranscribeShelf TranscribeShelf.qml\nActionRing ActionRing.qml\nRingSettings RingSettings.qml\nSelectionActions SelectionActions.qml\nSelectionSettings SelectionSettings.qml\nQueueShelf QueueShelf.qml\nJobHistory JobHistory.qml\nShelfAudioMeter ShelfAudioMeter.qml\nShelfTextArea ShelfTextArea.qml\nNearbyShare NearbyShare.qml\nShelfPanelMaterial ShelfPanelMaterial.qml\nsingleton ShelfNavigation ShelfNavigation.qml\nNavigationSettings NavigationSettings.qml\nTranslateShelf TranslateShelf.qml\nBatteriesShelf BatteriesShelf.qml\n')
    state=root/'services/ShelfState.qml';text=state.read_text();text=text.replace(' property var capabilities:', ' property string translationText:""\n property var capabilities:',1);state.write_text(text)
    p=root/'services/MprisState.qml';s=p.read_text()
    if p.is_symlink():p.unlink()
    s=s.replace('    readonly property MprisPlayer activePlayer: {','    property var preferredPlayer:null\n    function selectPlayer(player){preferredPlayer=player}\n    readonly property MprisPlayer activePlayer: {\n        if(root.preferredPlayer && root.players.includes(root.preferredPlayer))return root.preferredPlayer;',1)
    p.write_text(s)
    p=root/'shell.qml';s=p.read_text();s += '\n' if not s.endswith('\n') else ''
    # Add transformation window next to the existing floating tray/player.
    s=s.replace('    FloatingMusic {','    SelectionActions {}\n    ActionRing {}\n    DragBasket {}\n    TransformWindow {}\n    FloatingMusic {',1)
    s=s.replace('    NotificationServer {','    NotificationServer {\n        inlineReplySupported:true',1)
    if 'TransformWindow {}' not in s:s=s.replace('FloatingMusic{','SelectionActions{}\n    ActionRing{}\n    DragBasket{}\n    TransformWindow{}\n    FloatingMusic{',1)
    p.write_text(s)
    import runpy
    runpy.run_path(str(Path(__file__).with_name('navigation.py')))['integrate'](root)
    runpy.run_path(str(Path(__file__).with_name('activity_redesign.py')))['integrate'](root)
    runpy.run_path(str(Path(__file__).with_name('settings_audit.py')))['integrate'](root)
    runpy.run_path(str(Path(__file__).with_name('media_polish.py')))['integrate'](root)


if __name__=='__main__':
    import sys
    integrate(sys.argv[1])
